  for i=1,len do s=(s*1664525+1013904223)%4294967296; out[i]=math.floor(s/65536)%256 end
  return out
end
local function _b64(data)
  local alpha="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
  data=string.gsub(data,"[^A-Za-z0-9+/=]","")
  local out,buf,nbits={},0,0
  for i=1,#data do
    local c=data:sub(i,i); if c=="=" then break end
    local v=(alpha:find(c,1,true) or 1)-1
    buf=buf*64+v; nbits=nbits+6
    if nbits>=8 then nbits=nbits-8; out[#out+1]=string.char(math.floor(buf/(2^nbits))%256); buf=buf%(2^nbits) end
  end
  return table.concat(out)
end
