  for i=1,n do local b=raw[i]; b=_bx(b,_bx(salt,(i-1)%256)); b=((b*16)%256)+math.floor(b/16); raw[i]=b end
  local ks=_ks(n,idx0); local chars=table.create(n)
  for i=1,n do chars[i]=string.char(_bx(raw[i],ks[i])) end
  return table.concat(chars)
end
